{"type":"item.completed","item":{"id":"item_23","type":"command_execution","command":"/bin/zsh -lc \"git show HEAD:service.go | nl -ba | sed -n '1,380p'\"","aggregated_output":"     1\tpackage agent\n     2\t\n     3\timport (\n     4\t\t\"context\"\n     5\t\t\"fmt\"\n     6\t\t\"io\"\n     7\t\t\"path/filepath\"\n     8\t\t\"sync\"\n     9\t\t\"time\"\n    10\t\n    11\t\t\"github.com/DocumentDrivenDX/agent/internal/harnesses\"\n    12\t\tclaudeharness \"github.com/DocumentDrivenDX/agent/internal/harnesses/claude\"\n    13\t)\n    14\t\n    15\t// DdxAgent is the entire public Go surface of the ddx-agent module.\n    16\t// See CONTRACT-003 for the full specification.\n    17\ttype DdxAgent interface {\n    18\t\tExecute(ctx context.Context, req ServiceExecuteRequest) (<-chan ServiceEvent, error)\n    19\t\tTailSessionLog(ctx context.Context, sessionID string) (<-chan ServiceEvent, error)\n    20\t\tListHarnesses(ctx context.Context) ([]HarnessInfo, error)\n    21\t\tListProviders(ctx context.Context) ([]ProviderInfo, error)\n    22\t\tListModels(ctx context.Context, filter ModelFilter) ([]ModelInfo, error)\n    23\t\tHealthCheck(ctx context.Context, target HealthTarget) error\n    24\t\tResolveRoute(ctx context.Context, req RouteRequest) (*RouteDecision, error)\n    25\t\tRouteStatus(ctx context.Context) (*RouteStatusReport, error)\n    26\t}\n    27\t\n    28\t// ServiceConfig provides provider and routing data to the service without\n    29\t// creating an import cycle from the root package into agent/config.\n    30\t// Callers wrap their loaded *config.Config in a type that satisfies this interface.\n    31\ttype ServiceConfig interface {\n    32\t\t// ProviderNames returns provider names in stable order (default first).\n    33\t\tProviderNames() []string\n    34\t\t// DefaultProviderName returns the name of the configured default provider.\n    35\t\tDefaultProviderName() string\n    36\t\t// Provider returns the raw config values for a named provider.\n    37\t\tProvider(name string) (ServiceProviderEntry, bool)\n    38\t\t// ModelRouteNames returns configured model-route names.\n    39\t\tModelRouteNames() []string\n    40\t\t// ModelRouteCandidates returns the provider names referenced by a route.\n    41\t\tModelRouteCandidates(routeName string) []string\n    42\t\t// ModelRouteConfig returns the full route config for a named route.\n    43\t\t// Returns zero value when the route is not found.\n    44\t\tModelRouteConfig(routeName string) ServiceModelRouteConfig\n    45\t\t// HealthCooldown returns the configured cooldown duration (0 = use default 30s).\n    46\t\tHealthCooldown() time.Duration\n    47\t\t// WorkDir is the base directory for file-backed health state.\n    48\t\tWorkDir() string\n    49\t}\n    50\t\n    51\t// ServiceModelRouteConfig carries the routing strategy and candidates for one route.\n    52\ttype ServiceModelRouteConfig struct {\n    53\t\tStrategy   string                       // \"priority-round-robin\" | \"ordered-failover\" | \"smart\" | \"\"\n    54\t\tCandidates []ServiceRouteCandidateEntry // ordered candidate list\n    55\t}\n    56\t\n    57\t// ServiceRouteCandidateEntry is one candidate inside a model route.\n    58\ttype ServiceRouteCandidateEntry struct {\n    59\t\tProvider string\n    60\t\tModel    string // may be empty (provider default)\n    61\t\tPriority int\n    62\t}\n    63\t\n    64\t// ServiceProviderEntry carries the minimal provider data the service needs.\n    65\ttype ServiceProviderEntry struct {\n    66\t\tType      string // \"openai\" | \"openrouter\" | \"lmstudio\" | \"omlx\" | \"ollama\" | \"anthropic\"\n    67\t\tBaseURL   string\n    68\t\tEndpoints []ServiceProviderEndpoint\n    69\t\tAPIKey    string\n    70\t\tModel     string // configured default model (may be empty)\n    71\t}\n    72\t\n    73\t// ServiceProviderEndpoint is one configured provider serving endpoint.\n    74\ttype ServiceProviderEndpoint struct {\n    75\t\tName    string\n    76\t\tBaseURL string\n    77\t}\n    78\t\n    79\t// ServiceOptions configures a DdxAgent instance.\n    80\t//\n    81\t// seamOptions is embedded so production builds (no testseam tag) get an\n    82\t// empty struct — making it a compile-time error to set seam fields without\n    83\t// the build tag. Test builds inherit the four CONTRACT-003 seams\n    84\t// (FakeProvider, PromptAssertionHook, CompactionAssertionHook,\n    85\t// ToolWiringHook) automatically.\n    86\ttype ServiceOptions struct {\n    87\t\tseamOptions\n    88\t\n    89\t\tConfigPath string    // optional override; default $XDG_CONFIG_HOME/ddx-agent/config.yaml\n    90\t\tLogger     io.Writer // optional; agent writes structured session logs internally regardless\n    91\t\n    92\t\t// ServiceConfig, when non-nil, supplies provider and routing data for\n    93\t\t// ListProviders and HealthCheck. Pass a value wrapping the loaded config.\n    94\t\t// When nil, those methods return an error.\n    95\t\tServiceConfig ServiceConfig\n    96\t}\n    97\t\n    98\t// QuotaState is a live quota snapshot for a harness. Nil means not applicable.\n    99\ttype QuotaState struct {\n   100\t\tWindows    []harnesses.QuotaWindow `json:\"windows\"`\n   101\t\tCapturedAt time.Time               `json:\"captured_at\"`\n   102\t\tFresh      bool                    `json:\"fresh\"`\n   103\t}\n   104\t\n   105\t// HarnessInfo describes a registered harness as defined in CONTRACT-003.\n   106\ttype HarnessInfo struct {\n   107\t\tName                 string\n   108\t\tType                 string // \"native\" | \"subprocess\"\n   109\t\tAvailable            bool\n   110\t\tPath                 string\n   111\t\tError                string\n   112\t\tIsLocal              bool\n   113\t\tIsSubscription       bool\n   114\t\tExactPinSupport      bool\n   115\t\tDefaultModel         string   // built-in default model when no override is supplied\n   116\t\tSupportedPermissions []string // subset of {\"safe\",\"supervised\",\"unrestricted\"}\n   117\t\tSupportedReasoning   []string // values such as {\"low\",\"medium\",\"high\",\"xhigh\",\"max\"}\n   118\t\tCostClass            string   // \"local\" | \"cheap\" | \"medium\" | \"expensive\"\n   119\t\tQuota                *QuotaState\n   120\t}\n   121\t\n   122\t// CooldownState describes an active routing cooldown for a provider.\n   123\ttype CooldownState struct {\n   124\t\tReason    string    // \"consecutive_failures\" | \"manual\" | etc.\n   125\t\tUntil     time.Time // when the cooldown expires\n   126\t\tFailCount int       // number of consecutive failures that triggered the cooldown\n   127\t\tLastError string    // last recorded error message, if available\n   128\t}\n   129\t\n   130\t// ProviderInfo describes a provider with live status per CONTRACT-003.\n   131\ttype ProviderInfo struct {\n   132\t\tName          string\n   133\t\tType          string // \"openai\" | \"openrouter\" | \"lmstudio\" | \"omlx\" | \"ollama\" | \"anthropic\" | \"virtual\"\n   134\t\tBaseURL       string\n   135\t\tEndpoints     []ServiceProviderEndpoint\n   136\t\tStatus        string // \"connected\" | \"unreachable\" | \"error: <msg>\"\n   137\t\tModelCount    int\n   138\t\tCapabilities  []string       // e.g. {\"tool_use\",\"streaming\",\"json_mode\"}\n   139\t\tIsDefault     bool           // matches the configured default_provider\n   140\t\tDefaultModel  string         // per-provider configured default model, if any\n   141\t\tCooldownState *CooldownState // nil if not in cooldown\n   142\t}\n   143\t\n   144\t// CostInfo holds per-token cost metadata for a model.\n   145\ttype CostInfo struct {\n   146\t\tInputPerMTok  float64 // USD per 1M input tokens; 0 = unknown/free\n   147\t\tOutputPerMTok float64 // USD per 1M output tokens; 0 = unknown/free\n   148\t}\n   149\t\n   150\t// PerfSignal holds observed performance data for a model.\n   151\ttype PerfSignal struct {\n   152\t\tSpeedTokensPerSec float64 // 0 = unknown\n   153\t\tSWEBenchVerified  float64 // 0 = unknown\n   154\t}\n   155\t\n   156\t// ModelInfo describes a model with full metadata per CONTRACT-003.\n   157\ttype ModelInfo struct {\n   158\t\tID            string\n   159\t\tProvider      string\n   160\t\tHarness       string\n   161\t\tContextLength int\n   162\t\tCapabilities  []string\n   163\t\tCost          CostInfo\n   164\t\tPerfSignal    PerfSignal\n   165\t\tAvailable     bool\n   166\t\tIsConfigured  bool   // matches an explicit model_routes entry\n   167\t\tIsDefault     bool   // matches the configured default model\n   168\t\tCatalogRef    string // canonical catalog reference if recognized\n   169\t\tRankPosition  int    // ordinal in latest discovery rank; -1 if unranked\n   170\t}\n   171\t\n   172\t// ModelFilter filters ListModels results.\n   173\ttype ModelFilter struct {\n   174\t\tHarness  string\n   175\t\tProvider string\n   176\t}\n   177\t\n   178\t// HealthTarget identifies what to health-check.\n   179\ttype HealthTarget struct {\n   180\t\tType string // \"harness\" | \"provider\"\n   181\t\tName string\n   182\t}\n   183\t\n   184\t// RouteRequest specifies a routing query.\n   185\ttype RouteRequest struct {\n   186\t\tModel       string\n   187\t\tProvider    string\n   188\t\tHarness     string\n   189\t\tModelRef    string\n   190\t\tReasoning   Reasoning\n   191\t\tPermissions string\n   192\t}\n   193\t\n   194\t// RouteDecision is the result of ResolveRoute.\n   195\ttype RouteDecision struct {\n   196\t\tHarness  string\n   197\t\tProvider string\n   198\t\tModel    string\n   199\t\tReason   string\n   200\t}\n   201\t\n   202\t// RouteStatusReport is returned by RouteStatus.\n   203\ttype RouteStatusReport struct {\n   204\t\tRoutes          []RouteStatusEntry\n   205\t\tGeneratedAt     time.Time\n   206\t\tGlobalCooldowns []CooldownState\n   207\t}\n   208\t\n   209\t// RouteStatusEntry describes one configured model route.\n   210\ttype RouteStatusEntry struct {\n   211\t\tMod