ts a tool invocation requested by the model in the internal\n    52\t// loop API.\n    53\ttype ToolCall struct {\n    54\t\tID        string          `json:\"id\"`\n    55\t\tName      string          `json:\"name\"`\n    56\t\tArguments json.RawMessage `json:\"arguments\"`\n    57\t}\n    58\t\n    59\t// Message is a single message in the internal conversation history.\n    60\ttype Message struct {\n    61\t\tRole       Role       `json:\"role\"`\n    62\t\tContent    string     `json:\"content,omitempty\"`\n    63\t\tToolCalls  []ToolCall `json:\"tool_calls,omitempty\"`\n    64\t\tToolCallID string     `json:\"tool_call_id,omitempty\"`\n    65\t}\n    66\t\n    67\t// ToolDef describes a tool for the internal LLM provider interface.\n    68\ttype ToolDef struct {\n    69\t\tName        string          `json:\"name\"`\n    70\t\tDescription string          `json:\"description\"`\n    71\t\tParameters  json.RawMessage `json:\"parameters\"` // JSON Schema\n    72\t}\n    73\t\n    74\ttype Reasoning = reasoning.Reasoning\n    75\t\n    76\tconst (\n    77\t\tReasoningAuto    = reasoning.ReasoningAuto\n    78\t\tReasoningOff     = reasoning.ReasoningOff\n    79\t\tReasoningLow     = reasoning.ReasoningLow\n    80\t\tReasoningMedium  = reasoning.ReasoningMedium\n    81\t\tReasoningHigh    = reasoning.ReasoningHigh\n    82\t\tReasoningMinimal = reasoning.ReasoningMinimal\n    83\t\tReasoningXHigh   = reasoning.ReasoningXHigh\n    84\t\tReasoningMax     = reasoning.ReasoningMax\n    85\t)\n    86\t\n    87\tfunc ReasoningTokens(n int) Reasoning {\n    88\t\treturn reasoning.ReasoningTokens(n)\n    89\t}\n    90\t\n    91\t// Options configures a single internal provider Chat call.\n    92\t//\n    93\t// SeamOptions is embedded to carry test injection seams when the testseam\n    94\t// build tag is set; in production builds it is an empty struct with no fields.\n    95\ttype Options struct {\n    96\t\tSeamOptions\n    97\t\n    98\t\tModel       string   `json:\"model,omitempty\"`\n    99\t\tTemperature *float64 `json:\"temperature,omitempty\"`\n   100\t\tSeed        int64    `json:\"seed,omitempty\"`\n   101\t\tMaxTokens   int      `json:\"max_tokens,omitempty\"`\n   102\t\tStop        []string `json:\"stop,omitempty\"`\n   103\t\t// Reasoning controls model-side reasoning with one scalar value. Empty means\n   104\t\t// unset; use ReasoningOff or ReasoningTokens(0) for explicit off.\n   105\t\tReasoning Reasoning `json:\"reasoning,omitempty\"`\n   106\t}\n   107\t\n   108\t// Response is the result of a single internal provider Chat call.\n   109\ttype Response struct {\n   110\t\tContent      string           `json:\"content\"`\n   111\t\tToolCalls    []ToolCall       `json:\"tool_calls,omitempty\"`\n   112\t\tUsage        TokenUsage       `json:\"usage\"`\n   113\t\tModel        string           `json:\"model\"`\n   114\t\tFinishReason string           `json:\"finish_reason\"`\n   115\t\tAttempt      *AttemptMetadata `json:\"attempt,omitempty\"`\n   116\t}\n   117\t\n   118\t// Provider is the internal interface that LLM backends implement.\n   119\ttype Provider interface {\n   120\t\tChat(ctx context.Context, messages []Message, tools []ToolDef, opts Options) (Response, error)\n   121\t}\n   122\t\n   123\t// Tool is the internal interface that agent tools implement.\n   124\ttype Tool interface {\n   125\t\t// Name returns the tool's identifier.\n   126\t\tName() string\n   127\t\t// Description returns a human-readable description for the LLM.\n   128\t\tDescription() string\n   129\t\t// Schema returns the JSON Schema for the tool's parameters.\n   130\t\tSchema() json.RawMessage\n","exit_code":0,"status":"completed"}}
