t to the model. Used by tests that verify prompt\n    45\t// construction/compaction without running a real provider.\n    46\ttype PromptAssertionHook func(systemPrompt, userPrompt string, contextFiles []string)\n    47\t\n    48\t// CompactionAssertionHook is called whenever a real compaction runs. No-op\n    49\t// compactions are NOT delivered (they don't fire compaction events either).\n    50\ttype CompactionAssertionHook func(messagesBefore, messagesAfter int, tokensFreed int)\n    51\t\n    52\t// ToolWiringHook is called once per Execute with the resolved tool list and\n    53\t// the harness that received it. Used by tests that verify the right tools\n    54\t// land at the right harness given the request's permission level.\n    55\ttype ToolWiringHook func(harness string, toolNames []string)\n","exit_code":0,"status":"completed"}}
